"use client";
import { motion } from "framer-motion";
import { useEffect, useState } from "react";

export function HeroGraphic() {
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);

  if (!mounted) return null;

  return (
    <div className="relative w-full aspect-square max-w-[400px] mx-auto flex items-center justify-center opacity-80 mix-blend-difference dark:mix-blend-screen">
      {/* Ambient Glow */}
      <div className="absolute inset-0 bg-primary/20 rounded-full blur-[80px] animate-pulse" />
      
      {/* Outer Ring */}
      <motion.div 
        animate={{ rotate: 360 }}
        transition={{ duration: 40, repeat: Infinity, ease: "linear" }}
        className="absolute w-full h-full rounded-full border border-foreground/15 border-dashed flex items-center justify-center"
      >
        <div className="absolute -top-1.5 w-3 h-3 bg-primary rounded-full blur-[1px]" />
        <div className="absolute -bottom-1.5 w-3 h-3 bg-foreground/50 rounded-full" />
      </motion.div>

      {/* Middle Ring */}
      <motion.div 
        animate={{ rotate: -360 }}
        transition={{ duration: 25, repeat: Infinity, ease: "linear" }}
        className="absolute w-3/4 h-3/4 rounded-full border border-foreground/30 flex items-center justify-center"
      >
        <div className="absolute -left-1.5 w-3 h-3 bg-foreground rounded-full" />
      </motion.div>

      {/* Inner Ring */}
      <motion.div 
        animate={{ rotate: 360 }}
        transition={{ duration: 15, repeat: Infinity, ease: "linear" }}
        className="absolute w-1/2 h-1/2 rounded-full border border-primary/50 flex items-center justify-center"
      >
        <div className="absolute -right-2 w-4 h-4 bg-primary rounded-full shadow-[0_0_20px_rgba(153,0,0,1)]" />
      </motion.div>

      {/* Core */}
      <motion.div
        animate={{ scale: [1, 1.05, 1], opacity: [0.8, 1, 0.8] }}
        transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
        className="absolute w-1/4 h-1/4 bg-foreground rounded-full flex items-center justify-center shadow-[0_0_40px_rgba(0,0,0,0.1)] dark:shadow-[0_0_40px_rgba(255,255,255,0.1)]"
      >
        <span className="font-display text-background text-3xl font-bold tracking-tighter">E3</span>
      </motion.div>
    </div>
  );
}
